const express = require("express"); const cors = require("cors"); const app = express(); app.use(cors()); app.use(express.json()); let jobs = [ { id: 1, title: "React Developer", company: "TechCorp", location: "Remote", salary: "$80,000" }, { id: 2, title: "Full Stack Engineer", company: "Innovate AI", location: "Hybrid", salary: "$95,000" }, { id: 3, title: "Frontend Intern", company: "StartUp Inc", location: "On-site", salary: "$45,000" } ]; app.get("/api/health", (req, res) => res.json({ status: "ok", service: "CareerCompass AI backend" })); app.get("/api/jobs", (req, res) => res.json(jobs)); app.post("/api/jobs", (req, res) => { const newJob = { id: jobs.length + 1, ...req.body }; jobs.push(newJob); res.status(201).json(newJob); }); app.listen(8080, () => console.log("CareerCompass AI Backend running on port 8080"));
